const PORTFOLIO_CACHE_PREFIX='portfolio-cache-v1:';
let passwordRecoveryPending=false;
const PASSWORD_RECOVERY_COOLDOWN_KEY='portfolio-password-recovery-cooldown-until';
const PASSWORD_RECOVERY_COOLDOWN_MS=60*1000;
let passwordRecoveryCooldownUntil=0,passwordRecoveryCountdownTimer=null;
function readPortfolioCache(name){try{const value=localStorage.getItem(PORTFOLIO_CACHE_PREFIX+name);return value?JSON.parse(value):null}catch(error){console.warn('Could not read the portfolio cache:',error);return null}}
