async function loadDisciplines(){const{data,error}=await supabaseClient.from('portfolio_disciplines').select('id,name,sort_order,is_visible').order('sort_order',{ascending:true}).order('name',{ascending:true});if(error){toast('Could not load disciplines: '+error.message);return}disciplines=data||[];renderFilters();render();populateDisciplineSelect();renderStudioDisciplines()}
