function renderStudioDisciplines(){const box=document.getElementById('disciplineList');if(!box)return;const rows=[{id:'__all_work__',name:'All work',is_visible:portfolioSettings.show_all_work!==false,is_all_work:true},...disciplines];box.innerHTML=rows.map(d=>'<div class="discipline-row '+(d.is_visible===false?'is-hidden':'')+(d.is_all_work?' all-work-row':'')+'"><span class="discipline-name">'+esc(d.name)+'<small class="discipline-status">'+(d.is_visible===false?'Hidden from portfolio':'Visible on portfolio')+'</small></span><div class="discipline-actions"><button type="button" '+(d.is_all_work?'data-toggle-all-work':'data-toggle-discipline="'+esc(d.id)+'"')+' aria-label="'+(d.is_visible===false?'Show ':'Hide ')+esc(d.name)+'">'+(d.is_visible===false?'Show':'Hide')+'</button>'+(d.is_all_work?'':'<button type="button" data-delete-discipline="'+esc(d.id)+'">Delete</button>')+'</div></div>').join('')||'<p class="discipline-empty">No disciplines yet. Add one above.</p>';box.onclick=e=>{const allWork=e.target.closest('[data-toggle-all-work]');if(allWork){toggleAllWork();return}const toggle=e.target.closest('[data-toggle-discipline]');if(toggle){toggleDiscipline(toggle.dataset.toggleDiscipline);return}const remove=e.target.closest('[data-delete-discipline]');if(remove)deleteDiscipline(remove.dataset.deleteDiscipline)}}
async function toggleAllWork(){const visible=portfolioSettings.show_all_work!==false;const next=!visible;const{error}=await supabaseClient.from('portfolio_settings').update({show_all_work:next,updated_at:new Date().toISOString()}).eq('id',true);if(error){toast(error.message||'Could not update All work visibility.');return}portfolioSettings.show_all_work=next;writePortfolioCache('settings',portfolioSettings);if(!next&&active==='All')active=disciplines.find(d=>d.is_visible!==false)?.name||'All';renderFilters();render();renderStudioDisciplines();toast('All work filter '+(next?'shown':'hidden')+' on the portfolio.')}
async function toggleDiscipline(id){const discipline=disciplines.find(d=>d.id===id);if(!discipline)return;const isVisible=discipline.is_visible===false;const{error}=await supabaseClient.from('portfolio_disciplines').update({is_visible:isVisible}).eq('id',id);if(error){toast(error.message||'Could not update discipline visibility.');return}if(!isVisible&&active===discipline.name)active='All';await loadDisciplines();toast('“'+discipline.name+'” is now '+(isVisible?'visible':'hidden')+' on the portfolio.')}
async function addDiscipline(){const input=document.getElementById('newDiscipline'),button=document.getElementById('addDiscipline'),name=input.value.trim();if(!name){toast('Enter a discipline name.');return}if(name.length>40){toast('Discipline names must be 40 characters or fewer.');return}if(disciplines.some(d=>d.name.toLowerCase()===name.toLowerCase())){toast('That discipline already exists.');return}button.disabled=true;try{const sortOrder=Math.max(0,...disciplines.map(d=>Number(d.sort_order)||0))+10;const{error}=await supabaseClient.from('portfolio_disciplines').insert({name,sort_order:sortOrder});if(error)throw error;input.value='';await loadDisciplines();toast('Discipline added.')}catch(error){toast(error.message||'Could not add the discipline.')}finally{button.disabled=false}}
async function deleteDiscipline(id){const discipline=disciplines.find(d=>d.id===id);if(!discipline||!confirm('Delete the “'+discipline.name+'” discipline?'))return;const{count,error:countError}=await supabaseClient.from('projects').select('id',{count:'exact',head:true}).eq('category',discipline.name);if(countError){toast(countError.message);return}if(count){toast('Move the '+count+' project(s) in this discipline to another category before deleting it.');return}const{error}=await supabaseClient.from('portfolio_disciplines').delete().eq('id',id);if(error){toast(error.message);return}if(active===discipline.name)active='All';await loadDisciplines();toast('Discipline deleted.')}
async function loadPortfolioSettings(){const cached=readPortfolioCache('settings');if(cached&&typeof cached==='object'&&!Array.isArray(cached)){portfolioSettings={...portfolioSettings,...cached};applyPortfolioSettings();renderFilters();render()}const{data,error}=await supabaseClient.from('portfolio_settings').select('portrait_path,hero_cover_path,show_all_work').eq('id',true).maybeSingle();if(error){toast('Could not load site images: '+error.message);return}if(data){portfolioSettings={...portfolioSettings,...data};const result=await supabaseClient.from('portfolio_settings').select('site_content').eq('id',true).maybeSingle();if(!result.error&&result.data)portfolioSettings.site_content=result.data.site_content||{};writePortfolioCache('settings',portfolioSettings);applyPortfolioSettings();renderFilters();render()}}
async function saveSiteImage(fileId,column,buttonId,label){const input=document.getElementById(fileId),button=document.getElementById(buttonId),file=input&&input.files[0];if(!file){toast('Choose an image for '+label.toLowerCase()+' first.');return}button.disabled=true;button.textContent='Saving…';let newPath=null;try{newPath=await uploadCover(file);const oldPath=portfolioSettings[column];const patch={[column]:newPath,updated_at:new Date().toISOString()};const{error}=await supabaseClient.from('portfolio_settings').update(patch).eq('id',true);if(error)throw error;portfolioSettings[column]=newPath;writePortfolioCache('settings',portfolioSettings);applyPortfolioSettings();input.value='';if(oldPath){const{error:removeError}=await supabaseClient.storage.from(STORAGE_BUCKET).remove([oldPath]);if(removeError)toast(label+' updated; old image cleanup failed: '+removeError.message)}toast(label+' updated for the live site.')}catch(error){if(newPath)await supabaseClient.storage.from(STORAGE_BUCKET).remove([newPath]);toast(error.message||'Could not update '+label.toLowerCase()+'.')}finally{button.disabled=false;button.textContent='Save '+label}}
function showLogin(message='Sign in with your approved Studio account.'){editingProjectId=null;content.innerHTML='<form class="signin-form" id="signin"><h2>Welcome back.</h2><p>Sign in to manage projects in your studio.</p>'+(message?'<p class="hint">'+esc(message)+'</p>':'')+'<div class="field"><label for="email">Email address</label><input type="email" required autocomplete="username" placeholder="you@example.com" id="email"></div><div class="field"><label for="password">Password</label><input type="password" required autocomplete="current-password" placeholder="••••••••" id="password"></div><button class="submit" '+(!supabaseClient?'disabled':'')+'>Sign in to your studio ↗</button>'+(supabaseClient?'<button class="password-recovery-link" type="button" id="forgotPassword">Forgot password?</button>':'<p class="hint">Backend is not configured yet. Follow BACKEND_SETUP.md and add the Supabase Project URL and publishable key to backend-config.js.</p>')+'</form>';const form=document.getElementById('signin');form.onsubmit=async e=>{e.preventDefault();if(!supabaseClient)return;const button=form.querySelector('.submit');button.disabled=true;button.textContent='Signing in…';const{data,error}=await supabaseClient.auth.signInWithPassword({email:document.getElementById('email').value.trim(),password:document.getElementById('password').value});button.disabled=false;button.textContent='Sign in to your studio ↗';if(error){toast(error.message);return}await acceptSession(data.session,true)};const forgotButton=document.getElementById('forgotPassword');if(forgotButton){updatePasswordRecoveryButton();forgotButton.onclick=async()=>{const emailInput=document.getElementById('email');if(!emailInput.reportValidity())return;forgotButton.disabled=true;forgotButton.textContent='Sending recovery link…';try{if(!backendConfig.siteUrl)throw new Error('Password recovery is not configured with the live site URL.');const redirectTo=new URL(backendConfig.siteUrl).toString();const{error}=await supabaseClient.auth.resetPasswordForEmail(emailInput.value.trim(),{redirectTo});if(error)throw error;toast('If an account exists for that email, a recovery link has been sent.');startPasswordRecoveryCooldown()}catch(error){if(isPasswordRecoveryRateLimited(error)){startPasswordRecoveryCooldown();toast('Supabase is rate limiting recovery emails. Try again in at least 60 seconds; project limits may require a longer wait.')}else toast(error.message||'Could not send a recovery email.')}finally{updatePasswordRecoveryButton()}}}}
function showPasswordReset(){editingProjectId=null;modal.classList.remove('project-mode');modal.classList.add('open');content.innerHTML='<form class="signin-form" id="passwordReset"><h2>Reset your password.</h2><p>Choose a new password for your Studio account.</p><div class="field"><label for="resetPassword">New password</label><input type="password" id="resetPassword" required minlength="8" autocomplete="new-password"></div><div class="field"><label for="confirmResetPassword">Confirm new password</label><input type="password" id="confirmResetPassword" required minlength="8" autocomplete="new-password"></div><button class="submit">Save new password</button></form>';const form=document.getElementById('passwordReset'),button=form.querySelector('.submit');form.onsubmit=async event=>{event.preventDefault();const password=document.getElementById('resetPassword').value,confirmation=document.getElementById('confirmResetPassword').value;if(password!==confirmation){toast('The new passwords do not match.');return}button.disabled=true;button.textContent='Saving…';try{const{error}=await supabaseClient.auth.updateUser({password});if(error)throw error}catch(error){toast(error.message||'Could not reset the password.');button.disabled=false;button.textContent='Save new password';return}passwordRecoveryPending=false;form.reset();showLogin('Your password has been reset. Sign in with your new password.');try{const{error}=await supabaseClient.auth.signOut();if(error)throw error;toast('Password reset. Sign in with your new password.')}catch(error){toast('Your password was reset, but the recovery session could not be ended: '+error.message)}}}
function showStudio(){if(!currentUser){showLogin();return}content.innerHTML='<div class="upload-form show"><h2 id="studioHeading">Your studio.</h2><p id="studioHelp">Add a project and publish it to the live portfolio.</p><section class="visual-editor"><div class="visual-editor-head"><div><h3>Live page editor</h3><p>Click text in the preview to edit it. Click a project card to edit that project.</p></div><span class="visual-editor-hint">Select anything with the dashed outline</span></div><iframe id="visualFrame" src="index.html?visual-preview=1" title="Live portfolio preview"></iframe><div id="visualTextEditor" class="visual-text-editor" hidden><label id="visualTextLabel" for="visualText">Selected text</label><textarea id="visualText" rows="3"></textarea><div class="visual-text-actions"><span id="visualSaveStatus" aria-live="polite"></span><button type="button" class="submit" id="saveVisualText">Save text</button></div></div></section><form id="upload"><div class="field"><label for="ptitle">Project title</label><input required maxlength="120" placeholder="A name worth remembering" id="ptitle"></div><div class="field"><label for="pkind">Discipline</label><select id="pkind" style="border:1px solid var(--line);padding:12px;background:#fffefa"><option>Illustration</option></select></div><div class="field"><label for="pdescription">Description</label><textarea id="pdescription" rows="3" maxlength="1000" placeholder="A few words about the project"></textarea></div><div class="field"><label for="pfile">Cover image</label><div class="file-drop-zone" id="projectFileDrop"><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" id="pfile"><span class="file-drop-hint">Drop one cover image here or choose a file.</span></div><small>JPEG, PNG, WebP, or GIF; maximum 8 MB. The original and WebP preview are saved.</small></div><section class="batch-upload"><h3>Upload multiple projects</h3><p>Choose several images to create one project per file. The selected discipline will be used, and each project title will come from its filename.</p><div class="file-drop-zone" id="batchProjectDrop"><input type="file" id="batchProjectFiles" accept="image/jpeg,image/png,image/webp,image/gif" multiple><span class="file-drop-hint">Drop multiple images here or choose files.</span></div><p id="batchUploadStatus" class="batch-upload-status" aria-live="polite"></p></section><div class="project-submit-slot"><button type="button" class="submit" id="projectSubmit">Publish selected projects ↗</button><button type="button" class="submit cancel-edit" id="cancelEdit" hidden>Cancel edit</button></div><section class="storybook-upload"><h3>Create one storybook card</h3><p>Upload all pages of one story together. They will appear as one card under the Story book discipline.</p><div class="field"><label for="storybookTitle">Story title</label><input id="storybookTitle" maxlength="120" placeholder="Name this story"></div><div class="field"><label for="storybookFiles">Story pages</label><div class="file-drop-zone" id="storybookDrop"><input id="storybookFiles" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple><span class="file-drop-hint">Drop story pages here or choose files.</span></div><small>Select page images in reading order; files are sorted by filename.</small></div><div class="field" id="storybookCoverField" hidden><label for="storybookCoverSelect">Cover photo</label><select id="storybookCoverSelect"><option value="0">First page</option></select><small>This image appears on the project card.</small></div><button type="button" class="submit" id="publishStorybook">Publish storybook ↗</button><p id="storybookStatus" class="storybook-status" aria-live="polite"></p></section></form><section class="studio-settings"><h3>Site images</h3><p>Change the portrait on About and the cover image behind the Home hero.</p><div class="site-image-setting"><label class="mono" for="portraitFile">About profile photo</label><img class="site-image-preview portrait-preview" id="portraitPreview" data-default-src="assets/subrata-portrait.svg" src="assets/subrata-portrait.svg" alt="Current About portrait"><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" id="portraitFile"><button type="button" class="submit" id="savePortrait">Save About photo</button></div><div class="site-image-setting"><label class="mono" for="heroFile">Home page cover photo</label><div class="site-image-preview hero-preview" id="heroPreview"><span>No custom cover selected</span></div><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" id="heroFile"><button type="button" class="submit" id="saveHero">Save home cover</button></div></section><section class="discipline-manager"><h3>Disciplines</h3><p>Control the public filters. Hide or show All work and individual disciplines without deleting them.</p><div class="discipline-add"><input type="text" id="newDiscipline" maxlength="40" placeholder="e.g. Branding"><button type="button" class="submit" id="addDiscipline">Add discipline</button></div><div id="disciplineList" class="discipline-list"></div></section><section class="studio-account"><h3>Account settings</h3><p>Change your Studio login details. Email updates remain pending until the required confirmation is complete.</p><div class="account-current-email">Current email: <strong id="currentAccountEmail"></strong></div><form id="emailChange"><div class="field"><label for="accountEmail">New email address</label><input type="email" id="accountEmail" required autocomplete="email" placeholder="name@example.com"></div><div class="field"><label for="emailCurrentPassword">Current password</label><input type="password" id="emailCurrentPassword" required autocomplete="current-password"></div><button class="submit" id="changeEmailButton">Change email</button></form><p id="emailChangeStatus" class="email-change-status" aria-live="polite"></p><form id="passwordChange"><div class="field"><label for="passwordCurrentPassword">Current password</label><input type="password" id="passwordCurrentPassword" required autocomplete="current-password"></div><div class="field"><label for="newPassword">New password</label><input type="password" id="newPassword" required minlength="8" autocomplete="new-password"></div><div class="field"><label for="confirmPassword">Confirm new password</label><input type="password" id="confirmPassword" required minlength="8" autocomplete="new-password"></div><button class="submit" id="changePasswordButton">Change password</button></form></section><div id="existing"></div><button type="button" class="submit" id="logout" style="background:transparent;color:var(--ink);border:1px solid var(--line);margin-top:14px">Sign out</button></div>';document.getElementById('upload').onsubmit=publishPendingProjects;document.getElementById('projectSubmit').onclick=publishPendingProjects;const updatePublishReadiness=()=>{const count=document.getElementById('batchProjectFiles').files.length+(document.getElementById('pfile').files.length?1:0),button=document.getElementById('projectSubmit'),status=document.getElementById('batchUploadStatus');button.classList.toggle('has-upload',count>0);if(count)status.textContent=count+' project'+(count===1?'':'s')+' ready to publish.';else if(/ready to publish/.test(status.textContent))status.textContent=''};document.getElementById('batchProjectFiles').onchange=updatePublishReadiness;document.getElementById('publishStorybook').onclick=uploadStorybookProject;document.getElementById('storybookFiles').onchange=e=>{const files=Array.from(e.target.files||[]).sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'})),status=document.getElementById('storybookStatus'),coverField=document.getElementById('storybookCoverField'),coverSelect=document.getElementById('storybookCoverSelect');coverSelect.innerHTML=files.map((file,index)=>'<option value="'+index+'">'+esc(file.name)+'</option>').join('');coverField.hidden=!files.length;status.textContent=files.length?files.length+' page'+(files.length===1?'':'s')+' selected.':''};bindFileDropZone('projectFileDrop','pfile',false);bindFileDropZone('batchProjectDrop','batchProjectFiles',true);bindFileDropZone('storybookDrop','storybookFiles',true);document.getElementById('pfile').onchange=e=>{const file=e.target.files[0],title=document.getElementById('ptitle');if(file&&!title.value.trim())title.value=projectTitleFromFilename(file.name);updatePublishReadiness()};const visualText=document.getElementById('visualText'),visualFrame=document.getElementById('visualFrame');visualText.oninput=()=>visualFrame.contentWindow.postMessage({type:'visual-update-text',key:selectedVisualKey,value:visualText.value},location.origin);document.getElementById('saveVisualText').onclick=()=>selectedVisualKey&&saveVisualContent(selectedVisualKey,visualText.value.trim());document.getElementById('cancelEdit').onclick=cancelProjectEdit;document.getElementById('savePortrait').onclick=()=>saveSiteImage('portraitFile','portrait_path','savePortrait','About photo');document.getElementById('saveHero').onclick=()=>saveSiteImage('heroFile','hero_cover_path','saveHero','Home cover');document.getElementById('addDiscipline').onclick=addDiscipline;document.getElementById('currentAccountEmail').textContent=currentUser.email||'';document.getElementById('emailChange').onsubmit=changeStudioEmail;document.getElementById('passwordChange').onsubmit=changeStudioPassword;document.getElementById('portraitFile').onchange=e=>{const file=e.target.files[0];if(file)document.getElementById('portraitPreview').src=URL.createObjectURL(file)};document.getElementById('heroFile').onchange=e=>{const file=e.target.files[0],preview=document.getElementById('heroPreview');if(file){preview.style.backgroundImage='url("'+URL.createObjectURL(file)+'")';preview.classList.add('has-image')}};document.getElementById('logout').onclick=async()=>{await supabaseClient.auth.signOut();close()};applyPortfolioSettings();populateDisciplineSelect();renderStudioDisciplines();studioList()}
function projectTitleFromFilename(name){return String(name||'').replace(/\.[^.]+$/,'').replace(/[_]+/g,' ').trim().slice(0,120)}function bindFileDropZone(zoneId,inputId,multiple){const zone=document.getElementById(zoneId),input=document.getElementById(inputId);if(!zone||!input)return;['dragenter','dragover'].forEach(type=>zone.addEventListener(type,event=>{event.preventDefault();event.stopPropagation();zone.classList.add('is-dragover')}));['dragleave','dragend'].forEach(type=>zone.addEventListener(type,event=>{event.preventDefault();if(!zone.contains(event.relatedTarget))zone.classList.remove('is-dragover')}));zone.addEventListener('drop',event=>{event.preventDefault();event.stopPropagation();zone.classList.remove('is-dragover');const files=Array.from(event.dataTransfer?.files||[]).filter(file=>['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)).slice(0,multiple?files.length:1);if(!files.length)return;const transfer=new DataTransfer();files.forEach(file=>transfer.items.add(file));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))})}
async function uploadCover(file){if(!file)return null;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Choose a JPEG, PNG, WebP, or GIF image.');if(file.size>8*1024*1024)throw new Error('Cover images must be 8 MB or smaller.');const ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'})[file.type],path=crypto.randomUUID()+'.'+ext;const{error}=await supabaseClient.storage.from(STORAGE_BUCKET).upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path}
async function imageAsWebp(file){let bitmap;try{bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const context=canvas.getContext('2d');if(!context)throw new Error('Could not prepare the WebP preview.');context.drawImage(bitmap,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.86));if(!blob||blob.type!=='image/webp')throw new Error('This browser could not convert the image to WebP.');return blob}finally{bitmap?.close?.()}}
async function uploadProjectCover(file){if(!file)return null;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Choose a JPEG, PNG, WebP, or GIF image.');if(file.size>8*1024*1024)throw new Error('Cover images must be 8 MB or smaller.');const ext=({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'})[file.type],id=crypto.randomUUID(),originalPath=id+'-original.'+ext,previewPath=id+'-preview.webp',previewBlob=await imageAsWebp(file),storage=supabaseClient.storage.from(STORAGE_BUCKET);let uploaded=[];try{const originalResult=await storage.upload(originalPath,file,{contentType:file.type,upsert:false});if(originalResult.error)throw originalResult.error;uploaded.push(originalPath);const previewResult=await storage.upload(previewPath,previewBlob,{contentType:'image/webp',upsert:false});if(previewResult.error)throw previewResult.error;uploaded.push(previewPath);return{originalPath,previewPath}}catch(error){if(uploaded.length)await storage.remove(uploaded);throw error}}
function getProjectPreviewPath(originalPath){return originalPath&&/-original\.[^.]+$/i.test(originalPath)?originalPath.replace(/-original\.[^.]+$/i,'-preview.webp'):originalPath}

async function uploadStorybookProject(){if(!currentUser||!supabaseClient)return;const titleInput=document.getElementById('storybookTitle'),input=document.getElementById('storybookFiles'),button=document.getElementById('publishStorybook'),status=document.getElementById('storybookStatus'),title=titleInput.value.trim(),files=Array.from(input.files||[]).sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'}));if(!title){status.textContent='Enter a story title first.';titleInput.focus();return}if(!files.length){status.textContent='Choose the story page images first.';return}button.disabled=true;let uploaded=[];try{if(!disciplines.some(d=>d.name.toLowerCase()==='story book')){const sortOrder=Math.max(0,...disciplines.map(d=>Number(d.sort_order)||0))+10;const{error}=await supabaseClient.from('portfolio_disciplines').insert({name:'Story book',sort_order:sortOrder});if(error){await loadDisciplines();if(!disciplines.some(d=>d.name.toLowerCase()==='story book'))throw error}else await loadDisciplines()}for(let i=0;i<files.length;i++){status.textContent='Saving page '+(i+1)+' of '+files.length+': '+files[i].name;uploaded.push(await uploadProjectCover(files[i]))}const paths=uploaded.map(item=>item.originalPath),coverIndex=Math.max(0,Math.min(paths.length-1,Number(document.getElementById('storybookCoverSelect').value)||0)),coverPath=paths[coverIndex],slug=title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)+'-'+crypto.randomUUID().slice(0,8),sortOrder=Math.max(0,...getAllProjects().map(project=>Number(project.sort_order)||0))+10,{error}=await supabaseClient.from('projects').insert({slug,title,category:'Story book',year:new Date().getFullYear(),description:encodeStorybookDescription(document.getElementById('pdescription').value.trim(),paths),cover_path:coverPath,art_key:'custom',is_published:true,sort_order:sortOrder});if(error)throw error;uploaded=[];input.value='';titleInput.value='';status.textContent='Story published as one card with '+paths.length+' page'+(paths.length===1?'':'s')+'.';await loadProjects();studioList();toast('Storybook published as one project card.')}catch(error){if(uploaded.length){const paths=uploaded.flatMap(item=>[item.originalPath,item.previewPath]).filter(Boolean);await supabaseClient.storage.from(STORAGE_BUCKET).remove(paths)}status.textContent=error.message||'Could not publish the storybook.';toast(error.message||'Could not publish the storybook.')}finally{button.disabled=false}}
